insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('bmlt-ethicsprofessional1-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"The primary duty of a medical laboratory professional is to:","translation":"","options":["Provide accurate and reliable results","Finish tests as quickly as possible regardless of quality","Change results on request","Disclose results publicly"],"correctIndex":0,"explanation":"Patient safety depends on accurate, reliable and timely laboratory results.","explanationNe":"बिरामीको सुरक्षाका लागि सही, भरपर्दो र समयमै नतिजा दिनु प्रयोगशालाकर्मीको मुख्य जिम्मेवारी हो।","topic":"Professional ethics"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"Confidentiality means:","translation":"","options":["Sharing patient information only with authorized persons","Discussing results in public","Posting reports online","Giving reports to any visitor"],"correctIndex":0,"explanation":"Patient information must be protected and disclosed only through authorized channels.","explanationNe":"बिरामीको जानकारी सुरक्षित राखी अधिकारप्राप्त व्यक्तिलाई मात्र दिनुपर्छ।","topic":"Confidentiality"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"A laboratory report should be released only after:","translation":"","options":["Verification and authorization according to SOP","A verbal request from any person","Changing abnormal values","Removing patient identifiers"],"correctIndex":0,"explanation":"Results require appropriate review and authorization before release.","explanationNe":"नतिजा जारी गर्नुअघि SOP अनुसार जाँच र अधिकारप्राप्त व्यक्तिबाट प्रमाणीकरण आवश्यक हुन्छ।","topic":"Result reporting"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"A critical laboratory result should be:","translation":"","options":["Communicated promptly to an authorized clinician and documented","Kept until the next routine report","Ignored if the patient is not present","Posted on a notice board"],"correctIndex":0,"explanation":"Critical values require prompt notification, read-back where applicable and documentation.","explanationNe":"Critical result तुरुन्त सम्बन्धित चिकित्सकलाई जानकारी गराई अभिलेख राख्नुपर्छ।","topic":"Result reporting"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"Informed consent is based on:","translation":"","options":["Adequate information and voluntary agreement","Force or pressure","Concealing relevant information","Automatic consent for every procedure"],"correctIndex":0,"explanation":"Consent should be voluntary and based on understandable information about the procedure.","explanationNe":"सहमति स्वेच्छिक र परीक्षणबारे बुझिने जानकारी दिएपछि हुनुपर्छ।","topic":"Patient rights"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"A laboratory worker discovers that a result was entered for the wrong patient. The best action is to:","translation":"","options":["Immediately follow the correction and notification SOP","Delete all records without trace","Ignore the error","Alter another patient''s report"],"correctIndex":0,"explanation":"Wrong-patient errors must be corrected transparently with traceable documentation and notification.","explanationNe":"गलत बिरामीको नतिजा भए SOP अनुसार सच्याई अभिलेख र सम्बन्धित सूचना दिनुपर्छ।","topic":"Error management"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"The purpose of a standard operating procedure (SOP) is to:","translation":"","options":["Ensure consistent and controlled performance of tasks","Replace staff training entirely","Allow each worker to use any method","Avoid documentation"],"correctIndex":0,"explanation":"SOPs standardize procedures and support consistency, safety and quality.","explanationNe":"SOP ले कामको विधि एकरूप, सुरक्षित र गुणस्तरीय बनाउन मद्दत गर्छ।","topic":"Quality system"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"Which action best protects patient identity during specimen collection?","translation":"","options":["Use at least two approved patient identifiers","Use bed number alone","Label tubes later from memory","Use only the patient''s first name"],"correctIndex":0,"explanation":"Two approved identifiers reduce specimen identification errors.","explanationNe":"कम्तीमा दुई स्वीकृत पहिचान विवरण प्रयोग गर्दा नमुना गलत पहिचान हुने जोखिम घट्छ।","topic":"Specimen management"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"A specimen label should generally be applied:","translation":"","options":["At the patient''s side immediately after collection","At the end of the shift","Before confirming patient identity","Only after testing"],"correctIndex":0,"explanation":"Immediate bedside labelling reduces misidentification and mix-ups.","explanationNe":"नमुना संकलनपछि बिरामीकै छेउमा तुरुन्त label लगाउँदा गल्ती घट्छ।","topic":"Specimen management"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"A staff member should report a needle-stick injury:","translation":"","options":["Immediately according to exposure protocol","Only if symptoms develop","At the annual review","Never"],"correctIndex":0,"explanation":"Prompt reporting enables risk assessment, first aid and timely post-exposure management.","explanationNe":"तुरुन्त रिपोर्ट गर्दा जोखिम मूल्याङ्कन, प्राथमिक उपचार र आवश्यक post-exposure care सम्भव हुन्छ।","topic":"Occupational safety"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"The first action after a percutaneous exposure to blood is generally to:","translation":"","options":["Wash the area with soap and running water","Squeeze aggressively and apply bleach","Ignore the injury","Cover it without cleaning"],"correctIndex":0,"explanation":"Wash the exposed area promptly; then report and follow the exposure protocol.","explanationNe":"रगतको सम्पर्क भएको घाउ साबुनपानीले तुरुन्त धुनुपर्छ र exposure protocol पालना गर्नुपर्छ।","topic":"Occupational safety"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"A laboratory incident report is primarily used to:","translation":"","options":["Document events and support prevention of recurrence","Punish every staff member automatically","Hide errors","Replace patient records"],"correctIndex":0,"explanation":"Incident reporting supports learning, risk reduction and system improvement.","explanationNe":"Incident report ले घटना अभिलेख गरी दोहोरिन नदिन सुधार गर्न मद्दत गर्छ।","topic":"Risk management"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"Which is an example of a conflict of interest?","translation":"","options":["Accepting gifts that may influence test selection or reporting","Following validated procedures","Attending competency training","Maintaining confidentiality"],"correctIndex":0,"explanation":"Personal benefits must not compromise professional judgment or patient care.","explanationNe":"व्यक्तिगत लाभले व्यावसायिक निर्णय वा बिरामीको सेवामा असर पार्नु हुँदैन।","topic":"Professional conduct"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"A laboratory professional should handle a request to falsify a result by:","translation":"","options":["Refusing and reporting through the proper channel","Changing the result to satisfy the requester","Deleting the original record","Signing without checking"],"correctIndex":0,"explanation":"Falsification is unethical and can seriously harm patients.","explanationNe":"नतिजा जालसाजी गर्नु अनैतिक र बिरामीका लागि हानिकारक हुन्छ; उचित माध्यमबाट रिपोर्ट गर्नुपर्छ।","topic":"Professional conduct"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"The best way to maintain competence is to:","translation":"","options":["Participate in continuing education and competency assessment","Rely only on initial qualification","Avoid new procedures","Copy another worker''s results"],"correctIndex":0,"explanation":"Ongoing learning and assessment help maintain current professional competence.","explanationNe":"निरन्तर शिक्षा र दक्षता मूल्याङ्कनले व्यावसायिक क्षमता अद्यावधिक राख्छ।","topic":"Professional development"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"When a test result is inconsistent with the clinical picture, the laboratory should first:","translation":"","options":["Review identification, specimen quality, QC and analytical process","Immediately assume the clinician is wrong","Change the result without investigation","Discard the record"],"correctIndex":0,"explanation":"A systematic review can identify pre-analytical, analytical or post-analytical problems.","explanationNe":"नतिजा नमिलेमा पहिचान, नमुनाको गुणस्तर, QC र परीक्षण प्रक्रिया क्रमशः जाँच्नुपर्छ।","topic":"Result validation"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"Which document provides traceability of who performed and checked a test?","translation":"","options":["Appropriate laboratory record or audit trail","Personal diary only","Unlabelled scrap paper","Verbal handover alone"],"correctIndex":0,"explanation":"Traceable records identify actions, dates and responsible personnel.","explanationNe":"Traceable अभिलेखले काम गर्ने र जाँच गर्ने व्यक्ति तथा समय पहिचान गर्न मद्दत गर्छ।","topic":"Documentation"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',18,'{"question":"A patient asks for their own laboratory report. The laboratory should:","translation":"","options":["Follow the authorized report-release policy and verify identity","Give the report to anyone accompanying them","Refuse all patient access automatically","Read another patient''s report"],"correctIndex":0,"explanation":"Release should follow applicable policy, privacy rules and identity verification.","explanationNe":"बिरामीको रिपोर्ट दिनुअघि नीति पालना गरी पहिचान पुष्टि गर्नुपर्छ।","topic":"Patient rights"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',19,'{"question":"The main purpose of external quality assessment (EQA) is to:","translation":"","options":["Compare laboratory performance with an external scheme","Replace internal quality control","Calibrate every instrument automatically","Train patients"],"correctIndex":0,"explanation":"EQA provides an independent comparison of testing performance across laboratories.","explanationNe":"EQA ले प्रयोगशालाको परीक्षण कार्यसम्पादनलाई बाह्य योजनासँग तुलना गर्छ।","topic":"Quality assurance"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',20,'{"question":"A non-conforming specimen should be:","translation":"","options":["Handled using documented acceptance and rejection criteria","Tested without recording the problem","Relabelled from assumption","Mixed with another specimen"],"correctIndex":0,"explanation":"Specimen acceptance and rejection criteria should be predefined and consistently applied.","explanationNe":"नमुना स्वीकार वा अस्वीकार गर्ने मापदण्ड पहिल्यै तय गरी समान रूपमा लागू गर्नुपर्छ।","topic":"Specimen management"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"Which practice supports impartial laboratory services?","translation":"","options":["Applying the same validated criteria to all patients","Giving priority based on personal friendship","Altering results for payment","Withholding reports unfairly"],"correctIndex":0,"explanation":"Fair and consistent processes support impartiality and trust.","explanationNe":"सबै बिरामीमा समान प्रमाणित मापदण्ड लागू गर्दा निष्पक्षता कायम हुन्छ।","topic":"Professional conduct"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',22,'{"question":"If a colleague repeatedly ignores safety procedures, the appropriate response is to:","translation":"","options":["Address and report the risk through the established process","Copy the unsafe practice","Conceal the issue","Wait for an accident"],"correctIndex":0,"explanation":"Unsafe practices should be escalated through the laboratory''s safety system.","explanationNe":"असुरक्षित अभ्यासलाई प्रयोगशालाको सुरक्षा प्रणालीमार्फत जानकारी गराउनुपर्छ।","topic":"Occupational safety"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',23,'{"question":"A laboratory audit is conducted mainly to:","translation":"","options":["Assess compliance and identify improvement opportunities","Find reasons to hide records","Replace all QC activities","Guarantee no errors can occur"],"correctIndex":0,"explanation":"Audits evaluate whether activities meet defined requirements and identify improvements.","explanationNe":"Audit ले निर्धारित मापदण्ड पालना भएको छ कि छैन जाँची सुधारका अवसर खोज्छ।","topic":"Quality system"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',24,'{"question":"The correct response to a request for another person''s report without authorization is to:","translation":"","options":["Decline and explain the confidentiality requirements","Share it if the requester is curious","Send it to a public group","Leave it unattended"],"correctIndex":0,"explanation":"Unauthorized disclosure breaches patient privacy and confidentiality.","explanationNe":"अनुमति नभएको व्यक्तिलाई रिपोर्ट दिनु गोपनीयताको उल्लङ्घन हो।","topic":"Confidentiality"}'::jsonb,true),
('bmlt-ethicsprofessional1-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',25,'{"question":"A laboratory professional must maintain records so that they are:","translation":"","options":["Legible, accurate, secure and retrievable","Easily altered without trace","Stored without patient identifiers where required","Destroyed immediately after testing"],"correctIndex":0,"explanation":"Good records are readable, accurate, protected and retrievable for the required retention period.","explanationNe":"राम्रो अभिलेख स्पष्ट, सही, सुरक्षित र आवश्यक अवधिसम्म पुनःप्राप्त गर्न मिल्ने हुनुपर्छ।","topic":"Documentation"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-001','BMLT','BMLT NHPC Licensing','mock','free',1,'{"question":"Which ethical principle emphasizes avoiding harm to the patient?","translation":"","options":["Non-maleficence","Autonomy","Justice","Confidentiality"],"correctIndex":0,"explanation":"Non-maleficence means avoiding or minimizing harm.","explanationNe":"Non-maleficence को अर्थ बिरामीलाई हानि नगर्नु वा हानि न्यून गर्नु हो।","topic":"Professional ethics"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2,'{"question":"Respecting a competent patient''s decision after adequate explanation reflects:","translation":"","options":["Autonomy","Non-maleficence","Beneficence only","Confidentiality only"],"correctIndex":0,"explanation":"Autonomy respects a patient''s right to make informed decisions.","explanationNe":"Autonomy ले जानकारी पाएपछि बिरामीले निर्णय गर्ने अधिकारको सम्मान गर्छ।","topic":"Patient rights"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"Providing fair access to laboratory services reflects the principle of:","translation":"","options":["Justice","Fidelity","Veracity","Privacy"],"correctIndex":0,"explanation":"Justice concerns fairness and equitable treatment.","explanationNe":"Justice ले निष्पक्षता र समान व्यवहारलाई जनाउँछ।","topic":"Professional ethics"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-004','BMLT','BMLT NHPC Licensing','mock','free',4,'{"question":"The ethical principle of beneficence means:","translation":"","options":["Acting for the patient''s benefit","Avoiding all communication","Sharing private data","Following personal financial interests"],"correctIndex":0,"explanation":"Beneficence requires actions intended to benefit the patient.","explanationNe":"Beneficence भनेको बिरामीको हित हुने काम गर्नु हो।","topic":"Professional ethics"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"A laboratory result is amended after an error is identified. The record should:","translation":"","options":["Retain an audit trail of the original and amended result","Erase all evidence of the original result","Show no reason for amendment","Be changed without authorization"],"correctIndex":0,"explanation":"A traceable amendment preserves the original entry, reason, time and authorization.","explanationNe":"सच्याइएको रिपोर्टमा पुरानो विवरण, कारण, समय र अनुमति traceable रूपमा राख्नुपर्छ।","topic":"Documentation"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-006','BMLT','BMLT NHPC Licensing','mock','free',6,'{"question":"Which situation requires urgent communication rather than routine report dispatch?","translation":"","options":["A validated critical result","A normal routine result","A test with no result yet","A duplicate blank request"],"correctIndex":0,"explanation":"Critical results can require immediate clinical action and prompt notification.","explanationNe":"Critical result ले तत्काल उपचार निर्णय बदल्न सक्ने भएकाले तुरुन्त जानकारी दिनुपर्छ।","topic":"Result reporting"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-007','BMLT','BMLT NHPC Licensing','mock','free',7,'{"question":"A sample arrives without the required patient identifiers. The safest action is to:","translation":"","options":["Follow rejection or clarification policy before testing","Guess the patient''s identity","Use the ward number as the only identifier","Test and assign a name later"],"correctIndex":0,"explanation":"Unidentified specimens create serious patient safety risks and must follow defined policy.","explanationNe":"पहिचान नभएको नमुनाले बिरामी सुरक्षामा जोखिम ल्याउँछ; निर्धारित नीति पालना गर्नुपर्छ।","topic":"Specimen management"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-008','BMLT','BMLT NHPC Licensing','mock','free',8,'{"question":"A staff member notices a near miss that did not harm a patient. It should be:","translation":"","options":["Reported through the near-miss system","Ignored because no harm occurred","Hidden from the supervisor","Recorded as a normal result"],"correctIndex":0,"explanation":"Near-miss reporting helps identify hazards before harm occurs.","explanationNe":"हानि नभएको near miss पनि भविष्यको दुर्घटना रोक्न रिपोर्ट गर्नुपर्छ।","topic":"Risk management"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-009','BMLT','BMLT NHPC Licensing','mock','free',9,'{"question":"Which statement about passwords in a laboratory information system is correct?","translation":"","options":["Each user should use their own secure credentials","All staff should share one password","Passwords should be written on public screens","Former staff should retain access"],"correctIndex":0,"explanation":"Individual credentials support accountability and access control.","explanationNe":"व्यक्तिगत login ले जिम्मेवारी पहिचान र पहुँच नियन्त्रण गर्न मद्दत गर्छ।","topic":"Information security"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-010','BMLT','BMLT NHPC Licensing','mock','free',10,'{"question":"A laboratory information system user should access patient records:","translation":"","options":["Only when required for authorized work","Whenever curious","To look up neighbours'' results","To share interesting cases online"],"correctIndex":0,"explanation":"Access should be limited to legitimate work-related need.","explanationNe":"बिरामीको अभिलेख कामसँग सम्बन्धित वैध आवश्यकतामा मात्र खोल्नुपर्छ।","topic":"Information security"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-011','BMLT','BMLT NHPC Licensing','mock','free',11,'{"question":"A staff member is unsure whether a specimen can be accepted. They should:","translation":"","options":["Consult the SOP or authorized supervisor","Make an undocumented personal exception","Discard it without notification","Change the collection time"],"correctIndex":0,"explanation":"Uncertain cases should be resolved using documented policy and supervision.","explanationNe":"अनिश्चित अवस्थामा SOP वा अधिकारप्राप्त supervisor सँग परामर्श गर्नुपर्छ।","topic":"Specimen management"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-012','BMLT','BMLT NHPC Licensing','mock','free',12,'{"question":"Which action is appropriate when a reagent is expired?","translation":"","options":["Do not use it; follow disposal and replacement procedures","Use it if the colour looks normal","Change the expiry label","Mix it with fresh reagent"],"correctIndex":0,"explanation":"Expired reagents may compromise analytical performance and should be managed per policy.","explanationNe":"म्याद सकिएको reagent प्रयोग गर्नु हुँदैन; नीति अनुसार हटाई नयाँ राख्नुपर्छ।","topic":"Quality system"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-013','BMLT','BMLT NHPC Licensing','mock','free',13,'{"question":"A quality indicator is useful because it:","translation":"","options":["Measures performance over time","Guarantees every result is correct","Replaces staff training","Removes the need for audits"],"correctIndex":0,"explanation":"Quality indicators monitor processes and reveal trends needing improvement.","explanationNe":"Quality indicator ले समयअनुसार कार्यसम्पादन मापन गरी सुधार आवश्यक क्षेत्र देखाउँछ।","topic":"Quality assurance"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-014','BMLT','BMLT NHPC Licensing','mock','free',14,'{"question":"A laboratory should retain records for:","translation":"","options":["The period required by applicable policy and regulations","Exactly one day in every setting","No period at all","Only until the staff member leaves"],"correctIndex":0,"explanation":"Retention periods depend on applicable legal, accreditation and organizational requirements.","explanationNe":"अभिलेख राख्ने अवधि लागू कानुन, accreditation र संस्थाको नीतिअनुसार हुन्छ।","topic":"Documentation"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-015','BMLT','BMLT NHPC Licensing','mock','free',15,'{"question":"Which action best demonstrates professional accountability?","translation":"","options":["Taking responsibility for one''s work and reporting errors honestly","Blaming others automatically","Hiding mistakes","Signing tests not performed"],"correctIndex":0,"explanation":"Accountability includes ownership of actions and honest reporting.","explanationNe":"आफ्नो कामको जिम्मेवारी लिनु र गल्ती इमानदारीपूर्वक रिपोर्ट गर्नु accountability हो।","topic":"Professional conduct"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-016','BMLT','BMLT NHPC Licensing','mock','free',16,'{"question":"A patient''s identifiable case is discussed in a public lift. This is:","translation":"","options":["A breach of confidentiality","Acceptable if the result is abnormal","Required for teamwork","A form of informed consent"],"correctIndex":0,"explanation":"Patient-identifiable discussions should occur only in appropriate private settings.","explanationNe":"बिरामी चिनिने गरी सार्वजनिक स्थानमा कुरा गर्नु गोपनीयताको उल्लङ्घन हो।","topic":"Confidentiality"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-017','BMLT','BMLT NHPC Licensing','mock','free',17,'{"question":"The purpose of competency assessment is to confirm that staff:","translation":"","options":["Can perform assigned tasks to the required standard","Have memorized every SOP title","Can work without any supervision forever","Never need refresher training"],"correctIndex":0,"explanation":"Competency assessment evaluates the ability to perform specific tasks correctly.","explanationNe":"दक्षता मूल्याङ्कनले तोकिएको काम आवश्यक स्तरमा गर्न सक्ने क्षमता जाँच्छ।","topic":"Professional development"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-018','BMLT','BMLT NHPC Licensing','mock','free',18,'{"question":"When a laboratory receives a legal request for patient records, it should:","translation":"","options":["Verify authority and follow institutional legal procedures","Send all records immediately to any caller","Ignore every legal request","Post records publicly"],"correctIndex":0,"explanation":"Disclosure must follow applicable law, authorization and institutional procedures.","explanationNe":"कानुनी अनुरोधमा अधिकार पुष्टि गरी लागू कानुन र संस्थागत प्रक्रिया पालना गर्नुपर्छ।","topic":"Confidentiality"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-019','BMLT','BMLT NHPC Licensing','mock','free',19,'{"question":"Which is the best approach to a complaint about delayed results?","translation":"","options":["Acknowledge, investigate, document and respond through policy","Delete the complaint","Argue with the patient","Alter the test result"],"correctIndex":0,"explanation":"A structured complaint process supports service improvement and patient trust.","explanationNe":"गुनासो स्वीकार, छानबिन, अभिलेख र नीतिअनुसार जवाफ दिनुपर्छ।","topic":"Quality system"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-020','BMLT','BMLT NHPC Licensing','mock','free',20,'{"question":"A staff member should disclose a personal relationship that may bias a professional decision because it is a:","translation":"","options":["Potential conflict of interest","Routine calibration issue","Specimen rejection criterion","Critical value"],"correctIndex":0,"explanation":"Disclosure helps the organization manage actual or perceived conflicts impartially.","explanationNe":"व्यक्तिगत सम्बन्धले निर्णय प्रभावित गर्न सक्ने भए conflict of interest खुलाउनुपर्छ।","topic":"Professional conduct"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-021','BMLT','BMLT NHPC Licensing','mock','free',21,'{"question":"The safest way to correct a paper record is generally to:","translation":"","options":["Make a single-line correction, date and initial it per policy","Use correction fluid to hide the entry","Remove the page","Rewrite the entire log without explanation"],"correctIndex":0,"explanation":"Corrections should remain traceable and comply with the record-control procedure.","explanationNe":"कागजी अभिलेख सच्याउँदा पुरानो विवरण देखिने गरी नीति अनुसार मिति र initials राख्नुपर्छ।","topic":"Documentation"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-022','BMLT','BMLT NHPC Licensing','mock','free',22,'{"question":"A laboratory should investigate repeated specimen rejection mainly to:","translation":"","options":["Identify and reduce the underlying causes","Increase rejection numbers","Blame the collection staff without evidence","Stop recording rejections"],"correctIndex":0,"explanation":"Trend analysis can reveal training, collection or transport problems.","explanationNe":"बारम्बार नमुना अस्वीकार हुनुको मूल कारण खोज्दा तालिम, संकलन वा ढुवानी समस्या सुधार्न सकिन्छ।","topic":"Quality improvement"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-023','BMLT','BMLT NHPC Licensing','mock','free',23,'{"question":"Which is an appropriate practice when communicating a result by telephone?","translation":"","options":["Verify the recipient and document the communication","Read it to any person who answers","Leave detailed results on a public voicemail","Skip read-back for critical values"],"correctIndex":0,"explanation":"Recipient verification and documentation reduce communication errors; critical results may require read-back.","explanationNe":"फोनमा नतिजा दिँदा प्राप्तकर्ताको पहिचान रेकर्ड गर्नुपर्छ; critical value मा read-back आवश्यक पर्न सक्छ।","topic":"Result reporting"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-024','BMLT','BMLT NHPC Licensing','mock','free',24,'{"question":"A laboratory professional who identifies a possible sample mix-up should:","translation":"","options":["Stop release, investigate and notify relevant personnel","Release both results quickly","Choose the more plausible patient","Change labels without records"],"correctIndex":0,"explanation":"Suspected mix-ups require containment, investigation and documented corrective action.","explanationNe":"नमुना साटिएको शंका भए रिपोर्ट रोक्दै छानबिन र अभिलेखसहित सुधार गर्नुपर्छ।","topic":"Error management"}'::jsonb,true),
('bmlt-ethicsprofessional1-mock-025','BMLT','BMLT NHPC Licensing','mock','free',25,'{"question":"The main purpose of corrective action is to:","translation":"","options":["Remove the cause of a detected nonconformity","Hide the evidence","Repeat the same test indefinitely","Punish patients"],"correctIndex":0,"explanation":"Corrective action addresses root causes to prevent recurrence.","explanationNe":"Corrective action ले nonconformity को मूल कारण हटाई पुनरावृत्ति रोक्छ।","topic":"Quality improvement"}'::jsonb,true)
