-- BMLT NHPC preparation: Medical Ethics, Professional Practice & Laboratory Governance Batch 1
-- 25 MCQ Practice + 25 Mock Test questions
begin;
on conflict (content_id) do nothing;
commit;

select content_type, count(*) as question_count
from public.learning_content
where faculty='BMLT'
  and subject='BMLT NHPC Licensing'
  and content_data->>'topic' in ('Professional ethics','Confidentiality','Result reporting','Patient rights','Error management','Quality system','Specimen management','Occupational safety','Professional conduct','Professional development','Result validation','Documentation','Quality assurance','Risk management','Information security','Immunopathology','Quality improvement')
group by content_type
order by content_type;
